//! The C ABI for the mobile apps (`include/volna_core.h`, generated by
//! cbindgen). Dart reaches it through `dart:ffi`, Swift through a C target.
//!
//! Everything is asynchronous: [`volna_core_call`] and [`volna_core_proto`]
//! return at once and answer later through the registered callbacks, from a
//! core thread. Callbacks may fire on any thread and must not block; once a
//! `volna_core_set_*_callback` replaces one, it never runs again.
//!
//! Ownership: every `char *` and `uint8_t *` handed to a callback belongs to
//! the receiver, who frees it with [`volna_core_free_string`] /
//! [`volna_core_free_bytes`] (so a listener that runs later, like Dart's
//! `NativeCallable.listener`, can still read it). Strings passed into the
//! core are borrowed for the duration of the call only. All strings are
//! UTF-8, JSON where the name says so.
//!
//! Lifecycle: [`volna_core_init`] → set the callbacks → calls … →
//! [`volna_core_shutdown`] (never from inside a callback).

use std::ffi::{CStr, CString, c_char, c_void};
use std::path::PathBuf;
use std::sync::{Arc, RwLock};
use std::time::Duration;

use serde::Deserialize;
use serde_json::Value;

#[cfg(feature = "jni")]
mod jni;

use crate::core::{Core, CoreConfig, Dirs};
use crate::js::CallbackJs;
use crate::player::forward::EventSink;
use crate::player::platform::{CommandPlayer, PlatformOutput, PlayerReport};

/// The reply to [`volna_core_call`] `id`: `ok` → `json` is the result,
/// otherwise a JSON string with the error (`"<kind>: <message>"`).
pub type VolnaReplyCallback =
    Option<extern "C" fn(user_data: *mut c_void, id: u64, ok: bool, json: *mut c_char)>;
type ReplyFn = extern "C" fn(user_data: *mut c_void, id: u64, ok: bool, json: *mut c_char);
/// An event (`player:state`, `library:changed`, …) with its JSON payload.
pub type VolnaEventCallback =
    Option<extern "C" fn(user_data: *mut c_void, name: *mut c_char, payload_json: *mut c_char)>;
type EventFn = extern "C" fn(user_data: *mut c_void, name: *mut c_char, payload_json: *mut c_char);
/// The response to [`volna_core_proto`] `id`: HTTP status, headers as a
/// JSON array of `[name, value]` pairs, and the body.
pub type VolnaProtoCallback = Option<
    extern "C" fn(
        user_data: *mut c_void,
        id: u64,
        status: u16,
        headers_json: *mut c_char,
        body: *mut u8,
        body_len: usize,
    ),
>;
type ProtoFn = extern "C" fn(
    user_data: *mut c_void,
    id: u64,
    status: u16,
    headers_json: *mut c_char,
    body: *mut u8,
    body_len: usize,
);
/// A command for the platform player: `{"op":"load","url":…,"startMs":…}`,
/// `play`, `pause`, `{"op":"seek","positionMs":…}`, `stop`,
/// `{"op":"setVolume","volume":…}`. Report back with
/// [`volna_core_player_report`].
pub type VolnaPlayerCallback =
    Option<extern "C" fn(user_data: *mut c_void, command_json: *mut c_char)>;
type PlayerFn = extern "C" fn(user_data: *mut c_void, command_json: *mut c_char);
/// A JavaScript job for the platform's engine (WebView): `request_json` is
/// a `JsRequest` (docs/streams.md, "JsRuntime contract"). Evaluate
/// `volnaJs(<request_json>)` in a context where [`volna_core_js_prelude`] is
/// loaded and answer with the string it resolves to through
/// [`volna_core_js_result`]. Free `request_json` with
/// [`volna_core_free_string`].
pub type VolnaJsCallback =
    Option<extern "C" fn(user_data: *mut c_void, request_id: u64, request_json: *mut c_char)>;

/// A callback with its context pointer, callable from any thread.
struct Cb<F> {
    f: F,
    user: usize,
}

// The pointer is only handed back to the C side.
impl<F: Copy> Clone for Cb<F> {
    fn clone(&self) -> Self {
        Self {
            f: self.f,
            user: self.user,
        }
    }
}

impl<F: Copy> Cb<F> {
    fn user(&self) -> *mut c_void {
        self.user as *mut c_void
    }
}

type Slot<F> = Arc<RwLock<Option<Cb<F>>>>;

fn get<F: Copy>(slot: &Slot<F>) -> Option<Cb<F>> {
    slot.read().unwrap_or_else(|e| e.into_inner()).clone()
}

/// Calls the registered callback, if any, under the slot's read lock: once
/// [`set`] returns, the old callback is not running and never runs again,
/// so the host may free it (Dart closes its `NativeCallable`).
fn with<F: Copy>(slot: &Slot<F>, call: impl FnOnce(&Cb<F>)) {
    if let Some(cb) = slot.read().unwrap_or_else(|e| e.into_inner()).as_ref() {
        call(cb);
    }
}

fn set<F: Copy>(slot: &Slot<F>, f: Option<F>, user: *mut c_void) {
    *slot.write().unwrap_or_else(|e| e.into_inner()) = f.map(|f| Cb {
        f,
        user: user as usize,
    });
}

/// A Rust string as an owned C string (interior NULs dropped).
fn c_string(s: String) -> *mut c_char {
    let s = CString::new(s).unwrap_or_else(|e| {
        let mut v = e.into_vec();
        v.retain(|b| *b != 0);
        CString::new(v).expect("no NULs left")
    });
    s.into_raw()
}

/// A borrowed C string; `None` for NULL or invalid UTF-8.
///
/// # Safety
/// `p` is NULL or a valid NUL-terminated string.
unsafe fn borrowed<'a>(p: *const c_char) -> Option<&'a str> {
    if p.is_null() {
        return None;
    }
    // SAFETY: the caller promises a valid C string.
    unsafe { CStr::from_ptr(p) }.to_str().ok()
}

/// The opaque handle.
pub struct VolnaCore {
    runtime: Option<tokio::runtime::Runtime>,
    core: Arc<Core>,
    output: PlatformOutput,
    js: Arc<CallbackJs>,
    reply: Slot<ReplyFn>,
    event: Slot<EventFn>,
    proto: Slot<ProtoFn>,
    player: Slot<PlayerFn>,
}

impl VolnaCore {
    fn spawn(&self, f: impl Future<Output = ()> + Send + 'static) {
        if let Some(rt) = &self.runtime {
            rt.spawn(f);
        }
    }
}

struct FfiEvents(Slot<EventFn>);

impl EventSink for FfiEvents {
    fn connected(&self) -> bool {
        get(&self.0).is_some()
    }
    fn emit(&self, name: &str, payload: Value) {
        with(&self.0, |cb| {
            (cb.f)(cb.user(), c_string(name.to_owned()), c_string(payload.to_string()));
        });
    }
}

/// `volna_core_init` configuration.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct InitConfig {
    /// The app's private data directory (databases, settings, queue).
    data_dir: PathBuf,
    /// A cache directory the OS may clear (covers); default `<dataDir>/cache`.
    #[serde(default)]
    cache_dir: Option<PathBuf>,
    /// Serve audio to the platform player on `http://127.0.0.1:<port>/`.
    #[serde(default = "yes")]
    audio_server: bool,
    /// A `tracing` filter (e.g. `"info"`) to log to stderr; none by default.
    #[serde(default)]
    log: Option<String>,
    /// Debug builds only: route everything through this proxy URL
    /// (`socks5h://10.0.2.2:1081` from the Android emulator to the host).
    /// Mobile is direct-only; this exists for testing from a country where
    /// YouTube Music is blocked. Ignored (with a warning) in release builds.
    #[serde(default)]
    dev_proxy: Option<String>,
    /// Debug builds only: resolve every track to this URL (it must answer
    /// HTTP Range requests), to test the platform player through the
    /// loopback server without a real stream resolver. Ignored in release.
    #[serde(default)]
    dev_stream_url: Option<String>,
    /// The signed-in YouTube session for stream resolution, as a Netscape
    /// cookies.txt (from the login WebView's cookie store). Without it
    /// YouTube often answers with its bot check.
    #[cfg_attr(not(feature = "innertube"), allow(dead_code))]
    #[serde(default)]
    youtube_cookies: Option<String>,
}

fn yes() -> bool {
    true
}

/// `devStreamUrl`: every track is the same file.
struct DevStream(String);

impl volna_streams::Backend for DevStream {
    async fn resolve(
        &self,
        _id: &volna_streams::VideoId,
        _quality: volna_streams::Quality,
        _proxy: Option<&str>,
    ) -> volna_streams::Result<volna_streams::ResolvedStream> {
        Ok(volna_streams::ResolvedStream {
            url: self.0.clone(),
            delivery: volna_streams::Delivery::Url,
            format_id: "dev".into(),
            mime: "audio/webm".into(),
            codec: Some("opus".into()),
            bitrate_kbps: None,
            filesize: None,
            expires_at: std::time::SystemTime::now() + Duration::from_secs(3600),
            user_agent: None,
        })
    }
}

fn dev_backend(url: Option<String>) -> Option<crate::StreamBackend> {
    let url = url.filter(|u| !u.is_empty())?;
    if !cfg!(debug_assertions) {
        tracing::warn!("devStreamUrl is ignored in release builds");
        return None;
    }
    tracing::warn!("devStreamUrl on: every track plays {url}");
    Some(crate::StreamBackend::injected(DevStream(url)))
}

thread_local! {
    static LAST_ERROR: std::cell::RefCell<Option<String>> = const { std::cell::RefCell::new(None) };
}

fn fail(e: impl std::fmt::Display) -> *mut VolnaCore {
    LAST_ERROR.with(|l| *l.borrow_mut() = Some(e.to_string()));
    std::ptr::null_mut()
}

/// Starts the core. `config_json`: `{"dataDir": "…", "cacheDir": "…"?,
/// "audioServer": true?, "log": "info"?, "youtubeCookies": "<cookies.txt>"?}`.
/// With feature `innertube` the core resolves streams itself and runs their
/// JavaScript through [`volna_core_set_js_callback`]. Returns NULL on failure; the
/// reason is then in [`volna_core_last_error`] on the same thread.
///
/// # Safety
/// `config_json` is NULL or a valid NUL-terminated string.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_init(config_json: *const c_char) -> *mut VolnaCore {
    // SAFETY: forwarded from the caller.
    let Some(text) = (unsafe { borrowed(config_json) }) else {
        return fail("config_json is NULL or not UTF-8");
    };
    let config: InitConfig = match serde_json::from_str(text) {
        Ok(c) => c,
        Err(e) => return fail(format!("bad config: {e}")),
    };
    if let Some(filter) = &config.log {
        let _ = tracing_subscriber::fmt()
            .with_env_filter(tracing_subscriber::EnvFilter::new(filter))
            .with_writer(std::io::stderr)
            .try_init();
    }
    let runtime = match tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .thread_name("volna-core")
        .build()
    {
        Ok(rt) => rt,
        Err(e) => return fail(format!("tokio: {e}")),
    };
    let output = PlatformOutput::new();
    let js = CallbackJs::new();
    let dirs = Dirs::under(config.data_dir, config.cache_dir);
    let backend = stream_backend(&js, &dirs, config.youtube_cookies.as_deref());
    let core_config = CoreConfig {
        dirs,
        proxy: false,
        audio_server: config.audio_server,
        // devStreamUrl (debug builds) wins over the real resolver.
        backend: dev_backend(config.dev_stream_url.clone()).or(backend),
    };
    let started = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        runtime.block_on(Core::start(core_config, Some(output.clone())))
    }));
    let core = match started {
        Ok(Ok(core)) => core,
        Ok(Err(e)) => return fail(format!("{e:#}")),
        Err(_) => return fail("panic while starting the core"),
    };
    if let Some(url) = config.dev_proxy.filter(|u| !u.is_empty()) {
        apply_dev_proxy(&runtime, &core, url);
    }
    let event: Slot<EventFn> = Arc::default();
    core.set_event_sink(Some(Arc::new(FfiEvents(event.clone()))));
    let player: Slot<PlayerFn> = Arc::default();
    {
        let slot = player.clone();
        output.set_player(Some(Arc::new(CommandPlayer(move |cmd| {
            with(&slot, |cb| {
                let json = serde_json::to_string(&cmd).unwrap_or_default();
                (cb.f)(cb.user(), c_string(json));
            });
        }))));
    }
    Box::into_raw(Box::new(VolnaCore {
        runtime: Some(runtime),
        core,
        output,
        js,
        reply: Arc::default(),
        event,
        proto: Arc::default(),
        player,
    }))
}

/// `devProxy`: debug builds only, bypassing the direct-only rule.
fn apply_dev_proxy(runtime: &tokio::runtime::Runtime, core: &Arc<Core>, url: String) {
    if !cfg!(debug_assertions) {
        tracing::warn!("devProxy is ignored in release builds");
        return;
    }
    let config = volna_net::ProxyConfig::Url(url);
    match runtime.block_on(crate::network::switch(&core.app, config)) {
        Ok(()) => tracing::warn!(proxy = ?core.app.net.status().proxy, "devProxy on"),
        Err(e) => tracing::error!("devProxy: {e}"),
    }
}

/// Why the last [`volna_core_init`] on this thread failed, or NULL.
/// Free with [`volna_core_free_string`].
#[unsafe(no_mangle)]
pub extern "C" fn volna_core_last_error() -> *mut c_char {
    LAST_ERROR
        .with(|l| l.borrow_mut().take())
        .map_or(std::ptr::null_mut(), c_string)
}

/// # Safety
/// `handle` is NULL or from [`volna_core_init`] and not shut down.
unsafe fn handle<'a>(h: *mut VolnaCore) -> Option<&'a VolnaCore> {
    // SAFETY: the caller promises a live handle.
    unsafe { h.as_ref() }
}

/// The loopback audio server's base URL (`http://127.0.0.1:<port>/`), or
/// NULL without one. Free with [`volna_core_free_string`].
///
/// # Safety
/// `handle` is NULL or a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_stream_base(handle: *mut VolnaCore) -> *mut c_char {
    // SAFETY: forwarded from the caller.
    unsafe { self::handle(handle) }
        .and_then(|h| h.core.app.stream_base.clone())
        .map_or(std::ptr::null_mut(), c_string)
}

/// Where [`volna_core_call`] replies go (NULL `callback`: dropped). When
/// this returns, the previous callback is not running and is never called
/// again, so it may be freed. Not from inside a callback (it would wait
/// for itself).
///
/// # Safety
/// `handle` is a live handle; `callback` stays valid until replaced.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_set_reply_callback(
    handle: *mut VolnaCore,
    callback: VolnaReplyCallback,
    user_data: *mut c_void,
) {
    // SAFETY: forwarded from the caller.
    if let Some(h) = unsafe { self::handle(handle) } {
        set(&h.reply, callback, user_data);
    }
}

/// Where events go (NULL `callback`: dropped).
///
/// # Safety
/// As [`volna_core_set_reply_callback`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_set_event_callback(
    handle: *mut VolnaCore,
    callback: VolnaEventCallback,
    user_data: *mut c_void,
) {
    // SAFETY: forwarded from the caller.
    if let Some(h) = unsafe { self::handle(handle) } {
        set(&h.event, callback, user_data);
    }
}

/// Where [`volna_core_proto`] responses go.
///
/// # Safety
/// As [`volna_core_set_reply_callback`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_set_proto_callback(
    handle: *mut VolnaCore,
    callback: VolnaProtoCallback,
    user_data: *mut c_void,
) {
    // SAFETY: forwarded from the caller.
    if let Some(h) = unsafe { self::handle(handle) } {
        set(&h.proto, callback, user_data);
    }
}

/// The platform player: commands for it go to `callback`.
///
/// # Safety
/// As [`volna_core_set_reply_callback`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_set_player_callback(
    handle: *mut VolnaCore,
    callback: VolnaPlayerCallback,
    user_data: *mut c_void,
) {
    // SAFETY: forwarded from the caller.
    if let Some(h) = unsafe { self::handle(handle) } {
        set(&h.player, callback, user_data);
    }
}

/// The platform's JavaScript engine: jobs for it go to `callback`.
///
/// # Safety
/// As [`volna_core_set_reply_callback`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_set_js_callback(
    handle: *mut VolnaCore,
    callback: VolnaJsCallback,
    user_data: *mut c_void,
) {
    // SAFETY: forwarded from the caller.
    let Some(h) = (unsafe { self::handle(handle) }) else {
        return;
    };
    let user = user_data as usize;
    h.js.set_sender(
        callback
            .map(|f| move |id: u64, request: String| f(user as *mut c_void, id, c_string(request))),
    );
}

/// Runs command `cmd` with `args_json` (NULL: no args); the reply comes
/// through the reply callback with the same `id`.
///
/// # Safety
/// `handle` is a live handle; `cmd` and `args_json` are NULL or valid strings.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_call(
    handle: *mut VolnaCore,
    id: u64,
    cmd: *const c_char,
    args_json: *const c_char,
) {
    // SAFETY: forwarded from the caller.
    let Some(h) = (unsafe { self::handle(handle) }) else {
        return;
    };
    // SAFETY: forwarded from the caller.
    let (cmd, args) = unsafe { (borrowed(cmd), borrowed(args_json)) };
    let parsed = match (cmd, args) {
        (None, _) => Err("bad_args: cmd is NULL or not UTF-8".to_owned()),
        (Some(cmd), None) => Ok((cmd.to_owned(), Value::Null)),
        (Some(cmd), Some(a)) => serde_json::from_str(a)
            .map(|a| (cmd.to_owned(), a))
            .map_err(|e| format!("bad_args: args are not JSON: {e}")),
    };
    let (core, reply) = (h.core.clone(), h.reply.clone());
    h.spawn(async move {
        let result = match parsed {
            Ok((cmd, args)) => core.call(&cmd, &args).await,
            Err(e) => Err(e),
        };
        let (ok, json) = match result {
            Ok(v) => (true, v.to_string()),
            Err(e) => (false, Value::String(e).to_string()),
        };
        with(&reply, |cb| (cb.f)(cb.user(), id, ok, c_string(json)));
    });
}

/// A GET of a `volna://` URI (cover images); the response comes through
/// the proto callback with the same `id`.
///
/// # Safety
/// `handle` is a live handle; `uri` is NULL or a valid string.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_proto(handle: *mut VolnaCore, id: u64, uri: *const c_char) {
    // SAFETY: forwarded from the caller.
    let Some(h) = (unsafe { self::handle(handle) }) else {
        return;
    };
    // SAFETY: forwarded from the caller.
    let uri = unsafe { borrowed(uri) }.unwrap_or_default().to_owned();
    let (core, slot) = (h.core.clone(), h.proto.clone());
    h.spawn(async move {
        let resp = match http::Request::get(uri.as_str()).body(Vec::new()) {
            Ok(req) => core.proto(req).await,
            Err(e) => crate::protocol::json_error(http::StatusCode::BAD_REQUEST, &e.to_string()),
        };
        let (parts, body) = resp.into_parts();
        let headers: Vec<(String, String)> = parts
            .headers
            .iter()
            .filter_map(|(k, v)| Some((k.to_string(), v.to_str().ok()?.to_owned())))
            .collect();
        let headers = serde_json::to_string(&headers).unwrap_or_else(|_| "[]".into());
        let body = body.into_boxed_slice();
        let len = body.len();
        with(&slot, |cb| {
            let ptr = Box::into_raw(body).cast::<u8>();
            (cb.f)(cb.user(), id, parts.status.as_u16(), c_string(headers), ptr, len);
        });
    });
}

/// What the platform player did: `{"type":"ready","durationMs":…}`,
/// `playing`, `paused`, `{"type":"position","positionMs":…}`,
/// `{"type":"buffering","on":…}`, `ended`, `{"type":"error","message":…}`.
/// False when the JSON is not a report.
///
/// # Safety
/// `handle` is a live handle; `event_json` is NULL or a valid string.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_player_report(
    handle: *mut VolnaCore,
    event_json: *const c_char,
) -> bool {
    // SAFETY: forwarded from the caller.
    let (Some(h), Some(json)) = (unsafe { self::handle(handle) }, unsafe {
        borrowed(event_json)
    }) else {
        return false;
    };
    match serde_json::from_str::<PlayerReport>(json) {
        Ok(report) => {
            h.output.report(report);
            true
        }
        Err(e) => {
            tracing::warn!("bad player report {json:?}: {e}");
            false
        }
    }
}

/// The answer to JS job `request_id`: when `ok`, `result_json` is the
/// string `volnaJs` resolved to, unchanged; otherwise why the job could not
/// run (no WebView, page gone). False when nothing waits for that id.
///
/// # Safety
/// `handle` is a live handle; `result_json` is NULL or a valid string.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_js_result(
    handle: *mut VolnaCore,
    request_id: u64,
    ok: bool,
    result_json: *const c_char,
) -> bool {
    // SAFETY: forwarded from the caller.
    let Some(h) = (unsafe { self::handle(handle) }) else {
        return false;
    };
    // SAFETY: forwarded from the caller.
    let json = unsafe { borrowed(result_json) }.unwrap_or("null");
    h.js.complete(request_id, ok, json)
}

/// The script the platform's JS context loads once before any JS job
/// (`volnaJs` and the challenge solver). Owned by the library: do not free.
#[unsafe(no_mangle)]
pub extern "C" fn volna_core_js_prelude() -> *const c_char {
    static PRELUDE: std::sync::OnceLock<std::ffi::CString> = std::sync::OnceLock::new();
    PRELUDE
        .get_or_init(|| {
            std::ffi::CString::new(crate::js::PRELUDE).expect("the prelude has no NUL bytes")
        })
        .as_ptr()
}

/// The mobile stream resolver: InnerTube with its JavaScript run by the
/// platform through `js` (feature `innertube`). Without the feature there
/// is no backend and playback reports an error.
#[cfg(feature = "innertube")]
fn stream_backend(
    js: &Arc<CallbackJs>,
    dirs: &Dirs,
    cookies: Option<&str>,
) -> Option<crate::StreamBackend> {
    use volna_streams::innertube::{CookieJar, InnerTube, InnerTubeOptions};
    let backend = InnerTube::new(
        js.clone(),
        InnerTubeOptions {
            cache_dir: Some(dirs.cache.join("players")),
            ..Default::default()
        },
    );
    backend.set_cookies(cookies.map(CookieJar::from_netscape));
    Some(crate::StreamBackend::injected(backend))
}

#[cfg(not(feature = "innertube"))]
fn stream_backend(
    _js: &Arc<CallbackJs>,
    _dirs: &Dirs,
    _cookies: Option<&str>,
) -> Option<crate::StreamBackend> {
    None
}

/// Frees a string the core handed out.
///
/// # Safety
/// `s` is NULL or a string from this library, freed once.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_free_string(s: *mut c_char) {
    if !s.is_null() {
        // SAFETY: made by `CString::into_raw` in `c_string`.
        drop(unsafe { CString::from_raw(s) });
    }
}

/// Frees a body the proto callback handed out.
///
/// # Safety
/// `ptr`/`len` are NULL/any or exactly what the proto callback received, freed once.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_free_bytes(ptr: *mut u8, len: usize) {
    if !ptr.is_null() {
        // SAFETY: made by `Box::<[u8]>::into_raw` with this length.
        drop(unsafe { Box::from_raw(std::ptr::slice_from_raw_parts_mut(ptr, len)) });
    }
}

/// Saves the player, stops the core and frees the handle. Not from inside
/// a callback; no callback fires after it returns.
///
/// # Safety
/// `handle` is NULL or a live handle, not used afterwards.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn volna_core_shutdown(handle: *mut VolnaCore) {
    if handle.is_null() {
        return;
    }
    // SAFETY: from `Box::into_raw` in `volna_core_init`.
    let mut h = unsafe { Box::from_raw(handle) };
    set(&h.reply, None, std::ptr::null_mut());
    set(&h.event, None, std::ptr::null_mut());
    set(&h.proto, None, std::ptr::null_mut());
    set(&h.player, None, std::ptr::null_mut());
    h.js.set_sender(None::<fn(u64, String)>);
    if let Some(rt) = h.runtime.take() {
        let core = h.core.clone();
        rt.block_on(async move { core.shutdown().await });
        rt.shutdown_timeout(Duration::from_secs(2));
    }
    h.output.set_player(None);
}

#[cfg(test)]
mod tests {
    //! Drives the C ABI the way a host does: through the `extern "C"`
    //! functions and callbacks only.
    use super::*;
    use std::sync::{Mutex, mpsc};

    #[derive(Debug)]
    enum Got {
        Reply(u64, bool, Value),
        Event(String, Value),
        Proto(u64, u16, Value, Vec<u8>),
        Player(Value),
    }

    type Tx = Mutex<mpsc::Sender<Got>>;

    fn take(s: *mut c_char) -> String {
        // SAFETY: the core handed it over; freed once here.
        let out = unsafe { CStr::from_ptr(s) }.to_str().unwrap().to_owned();
        unsafe { volna_core_free_string(s) };
        out
    }

    fn tx(user: *mut c_void) -> &'static Tx {
        // SAFETY: the test keeps the boxed sender alive for the whole test.
        unsafe { &*(user as *const Tx) }
    }

    extern "C" fn on_reply(user: *mut c_void, id: u64, ok: bool, json: *mut c_char) {
        let v = serde_json::from_str(&take(json)).unwrap();
        let _ = tx(user).lock().unwrap().send(Got::Reply(id, ok, v));
    }

    extern "C" fn on_event(user: *mut c_void, name: *mut c_char, payload: *mut c_char) {
        let (n, p) = (take(name), take(payload));
        let _ = tx(user)
            .lock()
            .unwrap()
            .send(Got::Event(n, serde_json::from_str(&p).unwrap()));
    }

    extern "C" fn on_proto(
        user: *mut c_void,
        id: u64,
        status: u16,
        headers: *mut c_char,
        body: *mut u8,
        len: usize,
    ) {
        let h = serde_json::from_str(&take(headers)).unwrap();
        // SAFETY: the body the core handed over, freed right after.
        let b = unsafe { std::slice::from_raw_parts(body, len) }.to_vec();
        unsafe { volna_core_free_bytes(body, len) };
        let _ = tx(user).lock().unwrap().send(Got::Proto(id, status, h, b));
    }

    extern "C" fn on_player(user: *mut c_void, cmd: *mut c_char) {
        let v = serde_json::from_str(&take(cmd)).unwrap();
        let _ = tx(user).lock().unwrap().send(Got::Player(v));
    }

    fn cstr(s: &str) -> CString {
        CString::new(s).unwrap()
    }

    fn wait(rx: &mpsc::Receiver<Got>, mut f: impl FnMut(&Got) -> bool) -> Got {
        let deadline = std::time::Instant::now() + Duration::from_secs(20);
        loop {
            let left = deadline.saturating_duration_since(std::time::Instant::now());
            let got = rx.recv_timeout(left).expect("timed out waiting");
            if f(&got) {
                return got;
            }
        }
    }

    #[test]
    fn smoke() {
        // A bad config fails with a reason.
        let bad = cstr("{}");
        // SAFETY: valid strings throughout; the handle is shut down once.
        unsafe {
            assert!(volna_core_init(bad.as_ptr()).is_null());
            assert!(take(volna_core_last_error()).contains("dataDir"));
        }

        let dir = tempfile::tempdir().unwrap();
        let config =
            cstr(&serde_json::json!({ "dataDir": dir.path(), "audioServer": false }).to_string());
        let (s, rx) = mpsc::channel();
        let user = Box::into_raw(Box::new(Mutex::new(s))) as *mut c_void;
        // SAFETY: as above; `user` outlives the handle.
        unsafe {
            let h = volna_core_init(config.as_ptr());
            assert!(!h.is_null(), "{}", take(volna_core_last_error()));
            volna_core_set_reply_callback(h, Some(on_reply), user);
            volna_core_set_event_callback(h, Some(on_event), user);
            volna_core_set_proto_callback(h, Some(on_proto), user);
            volna_core_set_player_callback(h, Some(on_player), user);

            // A command with the same reply shape as over IPC.
            let snap = cstr("player_snapshot");
            volna_core_call(h, 1, snap.as_ptr(), std::ptr::null());
            match wait(&rx, |g| matches!(g, Got::Reply(1, ..))) {
                Got::Reply(_, true, v) => {
                    assert_eq!(v["protocol"], 1);
                    assert_eq!(v["state"]["status"], "idle");
                }
                other => panic!("{other:?}"),
            }
            // Errors are JSON strings.
            let nope = cstr("no_such_command");
            let args = cstr("{}");
            volna_core_call(h, 2, nope.as_ptr(), args.as_ptr());
            match wait(&rx, |g| matches!(g, Got::Reply(2, ..))) {
                Got::Reply(_, false, Value::String(e)) => assert!(e.contains("unknown command")),
                other => panic!("{other:?}"),
            }
            // Mobile is direct only.
            let apply = cstr("net_apply");
            let proxy = cstr(r#"{"config":{"mode":"url","value":"socks5h://127.0.0.1:9"}}"#);
            volna_core_call(h, 3, apply.as_ptr(), proxy.as_ptr());
            match wait(&rx, |g| matches!(g, Got::Reply(3, ..))) {
                Got::Reply(_, false, Value::String(e)) => assert!(e.starts_with("unsupported")),
                other => panic!("{other:?}"),
            }

            // proto: a bad image request answers 400 with JSON and headers.
            let uri = cstr("volna://img/?s=80");
            volna_core_proto(h, 7, uri.as_ptr());
            match wait(&rx, |g| matches!(g, Got::Proto(7, ..))) {
                Got::Proto(_, status, headers, body) => {
                    assert_eq!(status, 400);
                    assert!(
                        headers
                            .as_array()
                            .unwrap()
                            .iter()
                            .any(|p| p[0] == "content-type")
                    );
                    let v: Value = serde_json::from_slice(&body).unwrap();
                    assert_eq!(v["status"], 400);
                }
                other => panic!("{other:?}"),
            }

            // The platform player: a queue loads the first track through it,
            // and its reports move the engine (events come back).
            let set_queue = cstr("player_set_queue");
            let q =
                cstr(r#"{"tracks":[{"id":"dQw4w9WgXcQ","title":"A"}],"startIndex":0,"play":true}"#);
            volna_core_call(h, 4, set_queue.as_ptr(), q.as_ptr());
            // No stream backend here, so the engine reports the failure as
            // an event instead of loading (it may come before the reply).
            let (mut replied, mut failed) = (false, false);
            wait(&rx, |g| {
                match g {
                    Got::Reply(4, true, _) => replied = true,
                    Got::Event(n, p) if n == "player:error" && p.is_object() => failed = true,
                    _ => {}
                }
                replied && failed
            });
            let report = cstr(r#"{"type":"nonsense"}"#);
            assert!(!volna_core_player_report(h, report.as_ptr()));
            let ok = cstr(r#"{"type":"paused"}"#);
            assert!(volna_core_player_report(h, ok.as_ptr()));

            assert!(!volna_core_js_result(h, 99, true, std::ptr::null()));
            volna_core_shutdown(h);
            drop(Box::from_raw(user as *mut Tx));
        }
        // Player commands only appear with a stream backend (covered by
        // the core tests); nothing else is pending.
        while let Ok(g) = rx.try_recv() {
            if let Got::Player(cmd) = g {
                panic!("unexpected player command {cmd}");
            }
        }
    }

    #[test]
    fn stream_base_and_dev_proxy() {
        let dir = tempfile::tempdir().unwrap();
        let config = cstr(
            &serde_json::json!({
                "dataDir": dir.path(),
                "devProxy": "socks5h://127.0.0.1:9",
            })
            .to_string(),
        );
        let (s, rx) = mpsc::channel();
        let user = Box::into_raw(Box::new(Mutex::new(s))) as *mut c_void;
        // SAFETY: valid strings; `user` outlives the handle.
        unsafe {
            let h = volna_core_init(config.as_ptr());
            assert!(!h.is_null(), "{}", take(volna_core_last_error()));
            // The audio server runs only with a stream backend (`innertube`).
            let base = volna_core_stream_base(h);
            assert_eq!(base.is_null(), !cfg!(feature = "innertube"));
            volna_core_free_string(base);
            volna_core_set_reply_callback(h, Some(on_reply), user);
            // Tests are debug builds, where devProxy applies.
            let cmd = cstr("net_settings");
            volna_core_call(h, 1, cmd.as_ptr(), std::ptr::null());
            match wait(&rx, |g| matches!(g, Got::Reply(1, ..))) {
                Got::Reply(_, true, v) => {
                    assert_eq!(v["status"]["mode"], "url", "{v}");
                    assert_eq!(v["status"]["proxy"], "socks5h://127.0.0.1:9");
                }
                other => panic!("{other:?}"),
            }
            volna_core_shutdown(h);
            assert!(volna_core_stream_base(std::ptr::null_mut()).is_null());
            drop(Box::from_raw(user as *mut Tx));
        }
    }

    /// The platform player contract end to end over the C ABI: with a
    /// stream backend (`devStreamUrl`), a queue loads the loopback URL into
    /// the platform player, and its reports drive the engine.
    #[test]
    fn platform_player_over_ffi() {
        let dir = tempfile::tempdir().unwrap();
        let config = cstr(
            &serde_json::json!({
                "dataDir": dir.path(),
                "devStreamUrl": "http://127.0.0.1:9/test.webm",
            })
            .to_string(),
        );
        let (s, rx) = mpsc::channel();
        let user = Box::into_raw(Box::new(Mutex::new(s))) as *mut c_void;
        // SAFETY: valid strings; `user` outlives the handle.
        unsafe {
            let h = volna_core_init(config.as_ptr());
            assert!(!h.is_null(), "{}", take(volna_core_last_error()));
            let base = take(volna_core_stream_base(h));
            assert!(base.starts_with("http://127.0.0.1:"), "{base}");
            volna_core_set_reply_callback(h, Some(on_reply), user);
            volna_core_set_event_callback(h, Some(on_event), user);
            volna_core_set_player_callback(h, Some(on_player), user);

            let set_queue = cstr("player_set_queue");
            let q = cstr(
                r#"{"tracks":[{"id":"dQw4w9WgXcQ","title":"A"}],"startIndex":0,"play":true}"#,
            );
            volna_core_call(h, 1, set_queue.as_ptr(), q.as_ptr());
            let load = wait(&rx, |g| matches!(g, Got::Player(c) if c["op"] == "load"));
            let Got::Player(load) = load else { unreachable!() };
            let url = load["url"].as_str().unwrap();
            assert!(url.starts_with(&base), "{url} not under {base}");
            assert!(url.contains("dQw4w9WgXcQ"), "{url}");

            // Ready → the engine asks the player to play; playing → state.
            let ready = cstr(r#"{"type":"ready","durationMs":60000}"#);
            assert!(volna_core_player_report(h, ready.as_ptr()));
            wait(&rx, |g| matches!(g, Got::Player(c) if c["op"] == "play"));
            let playing = cstr(r#"{"type":"playing"}"#);
            assert!(volna_core_player_report(h, playing.as_ptr()));
            wait(&rx, |g| {
                matches!(g, Got::Event(n, p) if n == "player:state" && p["status"] == "playing")
            });
            // A pause from the UI reaches the player.
            let pause = cstr("player_pause");
            volna_core_call(h, 2, pause.as_ptr(), std::ptr::null());
            wait(&rx, |g| matches!(g, Got::Player(c) if c["op"] == "pause"));
            volna_core_shutdown(h);
            drop(Box::from_raw(user as *mut Tx));
        }
    }
}
